import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    """
    Decode a base64-encoded JSON string, store the content in a CSV file,
    and return the path to the created file.
    """
    def _decode_payload(payload):
        if payload is None:
            raise ValueError("raw_string cannot be None")

        if isinstance(payload, str):
            payload_bytes = payload.strip().encode("utf-8")
        elif isinstance(payload, (bytes, bytearray)):
            payload_bytes = bytes(payload)
        else:
            payload_bytes = str(payload).strip().encode("utf-8")

        try:
            decoded_bytes = base64.b64decode(payload_bytes, validate=False)
        except Exception as exc:
            raise ValueError("Invalid base64 input") from exc

        try:
            decoded_text = decoded_bytes.decode("utf-8-sig")
        except UnicodeDecodeError as exc:
            raise ValueError("Decoded payload is not valid UTF-8 text") from exc

        try:
            return json.loads(decoded_text)
        except json.JSONDecodeError as exc:
            raise ValueError("Decoded payload is not valid JSON") from exc

    def _cell_value(value):
        if value is None:
            return ""
        if isinstance(value, (dict, list, tuple, set)):
            return json.dumps(value, ensure_ascii=False)
        return str(value)

    data = _decode_payload(raw_string)

    output_dir = output_dir or "."
    os.makedirs(output_dir, exist_ok=True)

    base_name = os.path.basename(filename) if filename else "output.csv"
    if not base_name.lower().endswith(".csv"):
        base_name += ".csv"
    file_path = os.path.join(output_dir, base_name)

    with open(file_path, "w", newline="", encoding="utf-8") as csv_file:
        if isinstance(data, list):
            if not data:
                pass
            elif all(isinstance(item, dict) for item in data):
                fieldnames = []
                seen = set()
                for item in data:
                    for key in item.keys():
                        if key not in seen:
                            seen.add(key)
                            fieldnames.append(str(key))

                if fieldnames:
                    writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
                    writer.writeheader()
                    for item in data:
                        row = {str(key): _cell_value(item.get(key)) for key in fieldnames}
                        writer.writerow(row)
            elif all(isinstance(item, (list, tuple)) for item in data):
                max_len = max((len(item) for item in data), default=0)
                if max_len > 0:
                    writer = csv.writer(csv_file)
                    writer.writerow([f"column_{i + 1}" for i in range(max_len)])
                    for item in data:
                        row = [_cell_value(item[i]) if i < len(item) else "" for i in range(max_len)]
                        writer.writerow(row)
            else:
                writer = csv.writer(csv_file)
                writer.writerow(["value"])
                for item in data:
                    writer.writerow([_cell_value(item)])
        elif isinstance(data, dict):
            fieldnames = [str(key) for key in data.keys()]
            if fieldnames:
                writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
                writer.writeheader()
                writer.writerow({str(key): _cell_value(value) for key, value in data.items()})
        else:
            writer = csv.writer(csv_file)
            writer.writerow(["value"])
            writer.writerow([_cell_value(data)])

    return file_path
